SUBROUTINE SETUP_TRANS(KSMAX, KDGL, KDLON, KLOEN, LDSPLIT, PSTRET, KTMAX, KRESOL, PWEIGHT, &
  &                    LDGRIDONLY, LDUSERPNM, LDKEEPRPNM, LDUSEFLT, LDSPSETUPONLY, LDPNMONLY, &
  &                    LDUSEFFTW, LD_ALL_FFTW, LDLL, LDSHIFTLL, CDIO_LEGPOL, CDLEGPOLFNAME, &
  &                    KLEGPOLPTR, KLEGPOLPTR_LEN)

USE PARKIND1,                    ONLY: JPRD, JPIM
USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_BOOL, C_INT, C_PTR, C_SIZE_T

IMPLICIT NONE

INTERFACE
SUBROUTINE SETUP_TRANS_CPP_BINDING_SP(KSMAX, KDGL, KDLON, KLOEN, KRESOL) &
  &  BIND(C, NAME="setup_trans_sp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KSMAX
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KDGL
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KDLON
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)    :: KLOEN(*)
  INTEGER(KIND=C_INT),           INTENT(INOUT) :: KRESOL
END SUBROUTINE SETUP_TRANS_CPP_BINDING_SP
SUBROUTINE SETUP_TRANS_CPP_BINDING_DP(KSMAX, KDGL, KDLON, KLOEN, KRESOL) &
  & BIND(C, NAME="setup_trans_dp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KSMAX
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KDGL
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KDLON
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)    :: KLOEN(*)
  INTEGER(KIND=C_INT),           INTENT(INOUT) :: KRESOL
END SUBROUTINE SETUP_TRANS_CPP_BINDING_DP
END INTERFACE

INTEGER(KIND=JPIM),           INTENT(IN)  :: KSMAX
INTEGER(KIND=JPIM),           INTENT(IN)  :: KDGL
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KDLON
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KLOEN(:)
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDSPLIT
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KTMAX
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: KRESOL
REAL(KIND=JPRD),    OPTIONAL, INTENT(IN)  :: PWEIGHT(:)
REAL(KIND=JPRD),    OPTIONAL, INTENT(IN)  :: PSTRET
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDGRIDONLY
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDUSEFLT
LOGICAL,            OPTIONAL, INTENT(IN)  :: LD_ALL_FFTW
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDUSERPNM
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDKEEPRPNM
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDSPSETUPONLY
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDPNMONLY
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDUSEFFTW
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDLL
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDSHIFTLL
CHARACTER(LEN=*),   OPTIONAL, INTENT(IN)  :: CDIO_LEGPOL
CHARACTER(LEN=*),   OPTIONAL, INTENT(IN)  :: CDLEGPOLFNAME
TYPE(C_PTR),        OPTIONAL, INTENT(IN)  :: KLEGPOLPTR
INTEGER(C_SIZE_T),  OPTIONAL, INTENT(IN)  :: KLEGPOLPTR_LEN

INTEGER(KIND=C_INT) :: IRESOL, IDLON

IF (PRESENT(KDLON)) THEN
  IDLON = KDLON
ELSE
  IDLON = -1
ENDIF
IF (PRESENT(KRESOL)) THEN
  IRESOL = 0
ELSE
  IRESOL = -1
ENDIF

#ifdef TRANS_SINGLE
CALL SETUP_TRANS_CPP_BINDING_SP(KSMAX, KDGL, IDLON, KLOEN, IRESOL)
#else
CALL SETUP_TRANS_CPP_BINDING_DP(KSMAX, KDGL, IDLON, KLOEN, IRESOL)
#endif

IF (PRESENT(KRESOL)) THEN
  KRESOL = IRESOL
ENDIF

END SUBROUTINE SETUP_TRANS
